def compute(vars):
    thereafter = vars["v1"]
    total = vars["v2"]
    if total == 0:
        return None

    value = (thereafter / total) * 100
    return {
        "value": value,
        "trace": {
            "thereafter_maturities": thereafter,
            "total_scheduled_maturities": total,
            "ratio": thereafter / total,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage",
            },
        },
    }
